<template><div data-ui-id="calendar-grid" class="calendar-wrap"><div class="weekday" v-for="name in names" :key="name">{{name}}</div><button v-for="(day,i) in cells" :key="i" class="calendar-cell" :class="day?level(day.totalTokens):'placeholder'" :title="day?`${day.date} · ${day.totalTokens} tokens`:'无数据'" @click="day&&$emit('select',day.date)">{{day?.date?.slice(8)||''}}</button></div></template>
<script setup>import {computed} from 'vue';import {calendarCells} from '../state/widget.js';const p=defineProps({days:Array});defineEmits(['select']);const names=['一','二','三','四','五','六','日'];const cells=computed(()=>calendarCells(p.days));const max=computed(()=>Math.max(1,...(p.days||[]).map(x=>x.totalTokens||0)));const level=d=>!d?'l0':`l${Math.min(5,Math.ceil(d.totalTokens/max.value*5))}`</script>
